const resp = $input.first().json;

if (resp.errors) {
  throw new Error('Fireflies API error: ' + JSON.stringify(resp.errors.map(e => e.message)));
}
const t = resp.data?.transcript ?? resp.transcript;
if (!t) {
  throw new Error('Unexpected Fireflies response shape. Top-level keys: ' + Object.keys(resp).join(', '));
}
if (!t.sentences || !t.sentences.length) {
  throw new Error('Transcript ' + (t.id || '?') + ' has no sentences yet — it may still be processing.');
}

// Deterministic speaker -> Participant letter mapping
const letters = 'ABCDEFGHIJKLMNOP';
const map = {};
let n = 0;
for (const s of t.sentences) {
  const name = s.speaker_name || 'Unknown';
  if (!(name in map)) map[name] = 'Participant ' + letters[n++];
}
const lines = t.sentences.map(s => `${map[s.speaker_name || 'Unknown']}: ${s.text}`);

return [{
  json: {
    transcriptId: t.id,
    sessionDate: t.date,
    durationMins: Math.round(t.duration || 0),
    speakerCount: Object.keys(map).length,
    transcriptText: lines.join('\n')
  }
}];

