// Convert the minutes markdown into Notion blocks (chunked under the 2000-char block limit)
const j = $input.first().json;
const md = j.message?.content || j.choices?.[0]?.message?.content || j.output || j.text;
if (!md) throw new Error('Could not read minutes from OpenAI node output.');

const meta = $('Apply Redactions').first().json;
const blocks = [];
for (const rawLine of md.split('\n')) {
  const line = rawLine.trimEnd();
  if (!line.trim()) continue;
  const rt = (text) => [{ type: 'text', text: { content: text.slice(0, 1990) } }];
  if (line.startsWith('# ')) {
    blocks.push({ object: 'block', type: 'heading_1', heading_1: { rich_text: rt(line.slice(2)) } });
  } else if (line.startsWith('## ')) {
    blocks.push({ object: 'block', type: 'heading_2', heading_2: { rich_text: rt(line.slice(3)) } });
  } else if (line.startsWith('- ') || line.startsWith('* ')) {
    blocks.push({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: rt(line.slice(2)) } });
  } else {
    // Handle **bold intro:** lines and plain paragraphs the same way (plain text, Notion-safe)
    blocks.push({ object: 'block', type: 'paragraph', paragraph: { rich_text: rt(line.replace(/\*\*/g, '')) } });
  }
}

const dateStr = meta.sessionDate ? new Date(meta.sessionDate).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10);
return [{ json: { pageTitle: `Augmented minutes — ${dateStr}`, childrenBlocks: blocks.slice(0, 95), transcriptId: $('Format Transcript').first().json.transcriptId } }];

const j = $input.first().json;
const raw = j.message?.content || j.choices?.[0]?.message?.content || j.output || j.text;
if (!raw) throw new Error('No entity list returned from OpenAI.');

let entities;
try {
  entities = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {
  throw new Error('Entity list was not valid JSON: ' + raw.slice(0, 300));
}
if (!Array.isArray(entities)) throw new Error('Entity list is not an array.');

const meta = $('Format Transcript').first().json;
let text = meta.transcriptText;

// Longest terms first so "Build Circle" is replaced before "Circle"
entities.sort((a, b) => (b.term || '').length - (a.term || '').length);

const counts = [];
for (const e of entities) {
  if (!e.term || !e.replacement) continue;
  const escaped = e.term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('\\b' + escaped + "(?:'s)?\\b", 'gi');
  const n = (text.match(re) || []).length;
  text = text.replace(re, e.replacement);
  if (n > 0) counts.push(`${e.term} x${n}`);
}

return [{ json: {
  scrubbedTranscript: text,
  redactionLog: counts.join(', '),
  entityCount: entities.length,
  sessionDate: meta.sessionDate,
  durationMins: meta.durationMins,
  speakerCount: meta.speakerCount
}}];
